`timescale 1ns / 1ps
`default_nettype none

// AMD JTAG-to-AXI Master (IP jtag_axi_host, AXI4-Lite, 32-bit data), generated by
// fpga/bringup/jtag_host/build.tcl (ADR-025).  Only used under Vivado.
module jtag_axi_master_xilinx (
    input  wire        clk,
    input  wire        rst,
    output wire [31:0] m_awaddr,
    output wire        m_awvalid,
    input  wire        m_awready,
    output wire [31:0] m_wdata,
    output wire [3:0]  m_wstrb,
    output wire        m_wvalid,
    input  wire        m_wready,
    input  wire [1:0]  m_bresp,
    input  wire        m_bvalid,
    output wire        m_bready,
    output wire [31:0] m_araddr,
    output wire        m_arvalid,
    input  wire        m_arready,
    input  wire [31:0] m_rdata,
    input  wire [1:0]  m_rresp,
    input  wire        m_rvalid,
    output wire        m_rready
);
    wire [2:0] awprot, arprot;
    jtag_axi_host u_ip (
        .aclk(clk), .aresetn(~rst),
        .m_axi_awaddr(m_awaddr), .m_axi_awprot(awprot), .m_axi_awvalid(m_awvalid), .m_axi_awready(m_awready),
        .m_axi_wdata(m_wdata), .m_axi_wstrb(m_wstrb), .m_axi_wvalid(m_wvalid), .m_axi_wready(m_wready),
        .m_axi_bresp(m_bresp), .m_axi_bvalid(m_bvalid), .m_axi_bready(m_bready),
        .m_axi_araddr(m_araddr), .m_axi_arprot(arprot), .m_axi_arvalid(m_arvalid), .m_axi_arready(m_arready),
        .m_axi_rdata(m_rdata), .m_axi_rresp(m_rresp), .m_axi_rvalid(m_rvalid), .m_axi_rready(m_rready));
    wire unused_prot = &{1'b0, awprot, arprot};
endmodule

`default_nettype wire
